contracts/FeeSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import {FeeVault} from "./FeeVault.sol";
import {IPonsCurve, IPonsEscrow, IPonsHook} from "./interfaces/IPons.sol";

interface IPlatformFeeSink {
    function platformFeeIn(address token) external payable;
    function owner() external view returns (address);
}

/// @title FeeSplitter
/// @notice The Pons creator fee recipient of one PonsEarn coin. Pons pays creator fees by crediting
///         this address in its fee escrow; `collect()` pulls them in and splits them: `platformBps` to
///         PonsEarn, the rest to the coin's X accounts in the FeeVault.
/// @dev Deployed once as an implementation by PonsEarnLauncher and then cloned (EIP-1167) per coin, so
///      the immutables below are shared by every clone while `token`, `curve`, `poolId` and
///      `platformBps` are each clone's own storage. There is deliberately no way to hand the Pons
///      recipient role to another address: the split a coin launched with is the split it keeps.
contract FeeSplitter is ReentrancyGuardTransient {
    using SafeERC20 for IERC20;

    uint256 public constant BPS = 10_000;

    address public immutable launcher;
    FeeVault public immutable feeVault;
    IPonsEscrow public immutable escrow;
    IPonsHook public immutable hook;

    address public token;
    address public curve;
    bytes32 public poolId;
    uint16 public platformBps;
    /// @notice Everything this splitter has paid out: to X accounts and to PonsEarn.
    uint256 public totalCollected;

    event Collected(uint256 amount, uint256 toPlatform, uint256 toRecipients);
    event TokenRecovered(address indexed erc20, address indexed to, uint256 amount);

    error OnlyLauncher();
    error OnlyOwner();
    error AlreadyInitialized();
    error NotInitialized();

    constructor(address launcher_, FeeVault feeVault_, IPonsEscrow escrow_, IPonsHook hook_) {
        launcher = launcher_;
        feeVault = feeVault_;
        escrow = escrow_;
        hook = hook_;
    }

    /// @dev Called by the launcher in the transaction that creates the clone and the coin.
    function initialize(address token_, address curve_, bytes32 poolId_, uint16 platformBps_) external {
        if (msg.sender != launcher) revert OnlyLauncher();
        if (token != address(0)) revert AlreadyInitialized();
        token = token_;
        curve = curve_;
        poolId = poolId_;
        platformBps = platformBps_;
    }

    /// @notice Pons's fee escrow pays claims here; anything else sent is split the same way.
    receive() external payable {}

    /// @notice Moves this coin's pending creator fees into the Pons escrow where this contract may
    ///         (the curve before graduation, the pool's ETH fees after), claims the escrow balance, and
    ///         splits everything held. Anyone may call it.
    /// @dev The sweeps are best effort: after graduation a sweep that needs a memecoin conversion is
    ///      reserved for Pons's own keeper, which sweeps pools regularly, and a coin in its graduation
    ///      gap has nothing to sweep. Neither may stop what is already claimable from being paid out.
    function collect() external nonReentrant returns (uint256 amount) {
        address token_ = token;
        if (token_ == address(0)) revert NotInitialized();

        IPonsCurve curve_ = IPonsCurve(curve);
        if (!curve_.graduated()) {
            // slither-disable-next-line unused-return
            try curve_.sweepFees(0) {} catch {}
        } else {
            try hook.sweepPoolFees(poolId, 0, 0) {} catch {}
        }
        if (escrow.balanceOf(address(this)) != 0) {
            // slither-disable-next-line unused-return
            escrow.claim();
        }

        amount = address(this).balance;
        // slither-disable-next-line incorrect-equality
        if (amount == 0) return 0;
        uint256 toPlatform = (amount * platformBps) / BPS;
        uint256 toRecipients = amount - toPlatform;
        totalCollected += amount;

        feeVault.deposit{value: toRecipients}(token_);
        // The launcher is immutable: PonsEarn's share can go nowhere else.
        // slither-disable-next-line arbitrary-send-eth
        if (toPlatform != 0) IPlatformFeeSink(launcher).platformFeeIn{value: toPlatform}(token_);
        emit Collected(amount, toPlatform, toRecipients);
    }

    /// @notice Creator fees this coin has earned but not yet split, in wei, before PonsEarn's share:
    ///         what sits in the curve's or the pool's ETH buckets, in the Pons escrow and here.
    /// @dev Pool fees taken in the coin itself are left out until Pons's keeper converts them to ETH.
    function pendingFees() public view returns (uint256 pending) {
        pending = escrow.balanceOf(address(this)) + address(this).balance;
        IPonsCurve curve_ = IPonsCurve(curve);
        if (address(curve_) == address(0)) return pending;
        uint256 protocolShare = curve_.protocolFeeShareBps();
        uint256 fees;
        uint256 tax;
        if (!curve_.graduated()) {
            fees = curve_.quoteFeeBalance();
            tax = curve_.creatorTaxBalance();
        } else {
            fees = hook.pendingFees(poolId, address(0));
            tax = hook.pendingCreatorTax(poolId, address(0));
        }
        pending += fees - (fees * protocolShare) / BPS + tax;
    }

    /// @notice Recovers an ERC-20 that ended up here (Pons's owner-only rescue can push a pool's
    ///         memecoin-denominated fees to the recipient). ETH is never recoverable this way: it is
    ///         always split by `collect()`.
    function recoverToken(address erc20, address to) external nonReentrant {
        if (msg.sender != IPlatformFeeSink(launcher).owner()) revert OnlyOwner();
        uint256 amount = IERC20(erc20).balanceOf(address(this));
        IERC20(erc20).safeTransfer(to, amount);
        emit TokenRecovered(erc20, to, amount);
    }
}

contracts/FeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/// @title FeeVault
/// @notice Holds the X (Twitter) accounts' share of PonsEarn coins' creator fees until their owners
///         claim it.
/// @dev Recipients are keyed by their numeric X user id, which never changes when an account is
///      renamed. `signer` is an off-chain service that
///        1. attests that a list of usernames maps to a list of X user ids when a coin is launched, and
///        2. signs a claim once the caller has proven ownership of an X account.
///      If the signer key ever leaks, the owner pauses claims, rotates the signer, and unpauses:
///      balances never move while paused, and signatures from the old signer stop working.
///      Launchers (PonsEarnLauncher) register splits; deposits are open to anyone, since they can
///      only add to what the recipients are owed.
contract FeeVault is Ownable2Step, ReentrancyGuard, EIP712 {
    uint256 public constant BPS = 10_000;
    uint256 public constant MAX_RECIPIENTS = 10;

    bytes32 public constant CLAIM_TYPEHASH = keccak256("Claim(uint64 xId,address to,uint256 nonce,uint256 deadline)");
    bytes32 public constant ATTESTATION_TYPEHASH =
        keccak256("SplitAttestation(address creator,uint64[] xIds,string[] handles,uint256 deadline)");

    struct Recipient {
        uint64 xId;
        uint16 bps;
    }

    address public signer;
    bool public claimsPaused;
    mapping(address launcher => bool) public isLauncher;

    mapping(address token => Recipient[]) private _splits;
    mapping(uint64 xId => address[]) private _tokensOf;
    mapping(address token => uint256) public tokenFees;
    /// @notice All fees ever split to X accounts, across every coin.
    uint256 public totalDeposited;
    mapping(uint64 xId => uint256) public claimable;
    mapping(uint64 xId => uint256) public totalEarned;
    mapping(uint64 xId => uint256) public nonces;

    event LauncherSet(address indexed launcher, bool allowed);
    event SignerSet(address indexed signer);
    event SplitSet(address indexed token, uint64[] xIds, uint16[] bps);
    event FeesDeposited(address indexed token, uint256 amount);
    event Claimed(uint64 indexed xId, address indexed to, uint256 amount);
    event ClaimsPausedSet(bool paused);

    error OnlyLauncher();
    error ZeroAddress();
    error InvalidSplit();
    error SplitExists();
    error NoSplit();
    error Expired();
    error BadSignature();
    error NothingToClaim();
    error TransferFailed();
    error ClaimsPaused();

    constructor(address owner_, address signer_) Ownable(owner_) EIP712("PonsEarn FeeVault", "1") {
        if (signer_ == address(0)) revert ZeroAddress();
        signer = signer_;
        emit SignerSet(signer_);
    }

    // ------------------------------------------------------------------ admin

    /// @notice Allows (or stops) a launcher registering splits. A launcher can only register splits
    ///         for new coins; it can never move a balance.
    function setLauncher(address launcher, bool allowed) external onlyOwner {
        if (launcher == address(0)) revert ZeroAddress();
        isLauncher[launcher] = allowed;
        emit LauncherSet(launcher, allowed);
    }

    function setClaimsPaused(bool paused) external onlyOwner {
        claimsPaused = paused;
        emit ClaimsPausedSet(paused);
    }

    function setSigner(address signer_) external onlyOwner {
        if (signer_ == address(0)) revert ZeroAddress();
        signer = signer_;
        emit SignerSet(signer_);
    }

    // --------------------------------------------------------------- launcher

    /// @notice Registers a coin's split after checking the signer's username → id attestation,
    ///         which is bound to the launching wallet.
    function setSplit(
        address token,
        address creator,
        uint64[] calldata xIds,
        string[] calldata handles,
        uint16[] calldata bps,
        uint256 deadline,
        bytes calldata attestation
    ) external {
        if (!isLauncher[msg.sender]) revert OnlyLauncher();
        uint256 n = xIds.length;
        if (n == 0 || n > MAX_RECIPIENTS || n != bps.length || n != handles.length) revert InvalidSplit();
        if (_splits[token].length != 0) revert SplitExists();
        if (block.timestamp > deadline) revert Expired();

        bytes32[] memory handleHashes = new bytes32[](n);
        uint256 sum = 0;
        for (uint256 i; i < n; ++i) {
            if (xIds[i] == 0 || bps[i] == 0) revert InvalidSplit();
            for (uint256 j; j < i; ++j) {
                if (xIds[j] == xIds[i]) revert InvalidSplit();
            }
            sum += bps[i];
            handleHashes[i] = keccak256(bytes(handles[i]));
            _splits[token].push(Recipient(xIds[i], bps[i]));
            _tokensOf[xIds[i]].push(token);
        }
        if (sum != BPS) revert InvalidSplit();

        bytes32 structHash = keccak256(
            abi.encode(
                ATTESTATION_TYPEHASH,
                creator,
                keccak256(abi.encodePacked(xIds)),
                keccak256(abi.encodePacked(handleHashes)),
                deadline
            )
        );
        if (ECDSA.recover(_hashTypedDataV4(structHash), attestation) != signer) revert BadSignature();

        emit SplitSet(token, xIds, bps);
    }

    /// @notice Credits `msg.value` to the coin's recipients according to its split.
    /// @dev Open to anyone: each coin's FeeSplitter deposits here, and tips can be routed the same way.
    function deposit(address token) external payable {
        Recipient[] storage split = _splits[token];
        uint256 n = split.length;
        if (n == 0) revert NoSplit();
        if (msg.value == 0) return;

        uint256 remaining = msg.value;
        for (uint256 i; i < n; ++i) {
            // Last recipient takes the rounding remainder so no wei is stranded.
            // msg.value is only divided up here, never spent more than once.
            // slither-disable-next-line msg-value-loop
            uint256 share = i == n - 1 ? remaining : (msg.value * split[i].bps) / BPS;
            remaining -= share;
            claimable[split[i].xId] += share;
            totalEarned[split[i].xId] += share;
        }
        tokenFees[token] += msg.value;
        totalDeposited += msg.value;
        emit FeesDeposited(token, msg.value);
    }

    // ------------------------------------------------------------------ claim

    /// @notice Sends everything owed to X account `xId` to `to`.
    /// @dev Anyone may submit the transaction; the signature binds the destination.
    function claim(uint64 xId, address to, uint256 deadline, bytes calldata signature)
        external
        nonReentrant
        returns (uint256 amount)
    {
        if (claimsPaused) revert ClaimsPaused();
        if (to == address(0)) revert ZeroAddress();
        if (block.timestamp > deadline) revert Expired();

        bytes32 structHash = keccak256(abi.encode(CLAIM_TYPEHASH, xId, to, nonces[xId], deadline));
        if (ECDSA.recover(_hashTypedDataV4(structHash), signature) != signer) revert BadSignature();

        amount = claimable[xId];
        if (amount == 0) revert NothingToClaim();

        nonces[xId]++;
        claimable[xId] = 0;

        // The destination is bound by the signer's EIP-712 signature, so it is not arbitrary.
        // slither-disable-next-line arbitrary-send-eth
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit Claimed(xId, to, amount);
    }

    // ------------------------------------------------------------------ views

    function getSplit(address token) external view returns (Recipient[] memory) {
        return _splits[token];
    }

    /// @notice The coins that pay X account `xId`, oldest first.
    function tokensOf(uint64 xId) external view returns (address[] memory) {
        return _tokensOf[xId];
    }

    /// @notice Claimable and lifetime earnings for several accounts in one call.
    function earningsOf(uint64[] calldata xIds)
        external
        view
        returns (uint256[] memory claimable_, uint256[] memory earned_)
    {
        claimable_ = new uint256[](xIds.length);
        earned_ = new uint256[](xIds.length);
        for (uint256 i; i < xIds.length; ++i) {
            claimable_[i] = claimable[xIds[i]];
            earned_[i] = totalEarned[xIds[i]];
        }
    }

    function domainSeparator() external view returns (bytes32) {
        return _domainSeparatorV4();
    }
}

contracts/interfaces/IPons.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

// The slices of Pons v2 (ponsfamily.com) on Robinhood Chain that PonsEarn talks to, transcribed
// from the verified sources and the Pons v2 integration docs. PonsEarn is not affiliated with Pons.

struct PonsSocials {
    string twitter;
    string telegram;
    string discord;
    string website;
    string farcaster;
}

struct PonsTokenParams {
    string name;
    string symbol;
    string logo;
    string description;
    PonsSocials socials;
    address creatorFeeRecipient;
    uint16 creatorTaxBps;
    bool buybackEnabled;
    bytes32 expectedEconomics; // previewLaunchEconomics(configId, pairToken); zero skips the check
    bytes32 salt; // CREATE2 salt, namespaced by Pons per launching account
}

/// @dev phase: 0 on the curve, 1 swept (curve closed, pool not created yet), 2 trading on Uniswap v4,
///      3 rescued by the Pons owner.
struct PonsLaunchedToken {
    address token;
    address curve;
    address deployer;
    address creatorFeeRecipient;
    address pairToken;
    uint256 graduationThreshold;
    uint24 poolFee;
    int24 tickSpacing;
    uint16 creatorTaxBps;
    bool buybackEnabled;
    uint8 phase;
    uint256 sweptQuote;
    uint256 sweptTokens;
    uint256 sweptAt;
    bool exists;
}

struct PonsFeePolicy {
    address protocolFeeRecipient;
    uint16 protocolFeeShareBps;
    uint16 buybackBurnBps;
    uint16 hookFeeBps;
    uint16 maxInternalPriceImpactBps;
}

interface IPonsFactory {
    function launchToken(
        PonsTokenParams calldata params,
        uint256 launchConfigId,
        address pairToken,
        address[] calldata snipeTaxExemptions
    ) external payable returns (address token, address curve);

    function createGraduatedPool(address token) external returns (uint256 positionId);

    function launchFee() external view returns (uint256);
    function canLaunch(address launcher) external view returns (bool);
    function maxCreatorTaxBps() external view returns (uint256);
    function previewLaunchEconomics(uint256 launchConfigId, address pairToken) external view returns (bytes32);
    function getLaunchedToken(address token) external view returns (PonsLaunchedToken memory);
    function getLaunchFeePolicy(address token) external view returns (PonsFeePolicy memory);
    function pendingCreatorFeeRecipient(address token)
        external
        view
        returns (address newRecipient, uint256 effectiveAt, uint256 expiresAt);
    function memeHook() external view returns (address);
    function feeEscrow() external view returns (address);
    function poolManager() external view returns (address);
}

interface IPonsCurve {
    function buy(uint256 quoteIn, uint256 minTokensOut, address recipient) external payable returns (uint256 tokensOut);
    function sell(uint256 tokensIn, uint256 minQuoteOut, address recipient) external returns (uint256 quoteOut);
    /// @dev Callable by the creator fee recipient while no buyback is earmarked (PonsEarn launches
    ///      never enable buybacks). Reverts once the curve has graduated.
    function sweepFees(uint256 minBuybackTokensOut) external;

    function getReserves() external view returns (uint256 quoteReserve, uint256 tokenReserve);
    function realQuoteReserve() external view returns (uint256);
    function sellableTokens() external view returns (uint256);
    function graduationThreshold() external view returns (uint256);
    function graduated() external view returns (bool);
    function feeBps() external view returns (uint256);
    function creatorTaxBps() external view returns (uint256);
    function quoteFeeBalance() external view returns (uint256);
    function creatorTaxBalance() external view returns (uint256);
    function protocolFeeShareBps() external view returns (uint16);
}

interface IPonsHook {
    /// @dev Callable by the pool's creator fee recipient when no internal swap is needed, that is
    ///      while no memecoin-denominated fees are pending; Pons's keeper sweeps the rest.
    function sweepPoolFees(bytes32 poolId, uint256 minConversionQuoteOut, uint256 minBuybackTokensOut) external;
    function pendingFees(bytes32 poolId, address currency) external view returns (uint256);
    function pendingCreatorTax(bytes32 poolId, address currency) external view returns (uint256);
}

interface IPonsEscrow {
    /// @dev Pays the caller's whole native balance; reverts with NoBalance() when it is zero.
    function claim() external returns (uint256 amount);
    function balanceOf(address recipient) external view returns (uint256);
}

interface IPonsToken {
    function logo() external view returns (string memory);
}

contracts/interfaces/IUniswapV4.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

// The parts of the Uniswap v4 PoolManager that a single-pool exact-input swap needs, matching
// v4-core's ABI (Currency and IHooks are plain addresses, BalanceDelta is a packed int256).

struct PoolKey {
    address currency0; // native ETH is address(0), which always sorts first
    address currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

struct SwapParams {
    bool zeroForOne;
    int256 amountSpecified; // negative: exact input
    uint160 sqrtPriceLimitX96;
}

interface IPoolManager {
    function unlock(bytes calldata data) external returns (bytes memory);
    /// @return swapDelta amount0 in the upper 128 bits, amount1 in the lower; negative = owed to the pool
    function swap(PoolKey memory key, SwapParams memory params, bytes calldata hookData) external returns (int256 swapDelta);
    function sync(address currency) external;
    function settle() external payable returns (uint256 paid);
    function take(address currency, address to, uint256 amount) external;
    function extsload(bytes32 slot) external view returns (bytes32 value);
}

interface IUnlockCallback {
    function unlockCallback(bytes calldata data) external returns (bytes memory);
}

contracts/PonsEarnLauncher.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {FeeVault} from "./FeeVault.sol";
import {FeeSplitter} from "./FeeSplitter.sol";
import {PonsEarnRouter} from "./PonsEarnRouter.sol";
import {
    IPonsCurve,
    IPonsEscrow,
    IPonsFactory,
    IPonsHook,
    IPonsToken,
    PonsLaunchedToken,
    PonsSocials,
    PonsTokenParams
} from "./interfaces/IPons.sol";
import {IPoolManager, PoolKey} from "./interfaces/IUniswapV4.sol";

/// @title PonsEarnLauncher
/// @notice Launches coins on Pons (ponsfamily.com) whose creator fees are split between up to 10 X
///         (Twitter) accounts. Pons mints the coin, runs its bonding curve and graduates it into a
///         locked Uniswap v4 pool exactly as for any other Pons launch; the only difference is that
///         the coin's creator fee recipient is a per-coin FeeSplitter:
///           - `platformShareBps` of the standard creator fee goes to PonsEarn,
///           - the rest of it, and the whole creator tax the launcher chose, goes to the X accounts.
///         PonsEarn is not affiliated with Pons.
/// @dev Pons's creator share is 70% of its 1% trade fee, plus the creator tax (0–10%). A splitter
///      cannot tell the two apart once Pons has paid them out, so each coin snapshots the fraction of
///      every payout that PonsEarn's share amounts to (`platformBps`) at launch.
contract PonsEarnLauncher is Ownable2Step, ReentrancyGuard {
    uint256 public constant BPS = 10_000;
    /// @notice PonsEarn never takes more than 30% of the standard creator fee.
    uint16 public constant MAX_PLATFORM_SHARE_BPS = 3_000;
    /// @dev Transient slot holding the curve allowed to refund ETH during a launch's first buy.
    bytes32 private constant REFUNDER_SLOT = keccak256("ponsearn.launcher.refunder");

    struct LaunchParams {
        string name;
        string symbol;
        string logo;
        string description;
        PonsSocials socials;
        uint16 creatorTaxBps;
        bytes32 salt; // any unused value; combined with the launching wallet
        bytes32 expectedEconomics; // Pons's previewLaunchEconomics, pinned so its terms can't move underneath
    }

    /// @notice What the signer attested for the fee split, plus the attestation itself.
    struct SplitParams {
        uint64[] xIds;
        string[] handles; // lowercase usernames at launch time (display only; ids are authoritative)
        uint16[] bps;
        uint256 deadline;
        bytes attestation;
    }

    struct Launch {
        address token;
        address curve;
        address splitter;
        address creator;
        uint64 createdAt;
        uint16 creatorTaxBps;
        uint16 platformBps; // share of every payout that goes to PonsEarn
        bytes32 poolId; // the Uniswap v4 pool it graduates into
    }

    struct LaunchView {
        Launch launch;
        string name;
        string symbol;
        string logo;
        uint8 phase; // Pons: 0 curve, 1 graduating, 2 Uniswap v4 pool, 3 rescued
        address feeRecipient; // Pons's current creator fee recipient (the splitter unless Pons moved it)
        uint256 quoteReserve; // curve pricing reserves, including the virtual ETH
        uint256 tokenReserve;
        uint256 raised; // real ETH on the curve
        uint256 threshold; // ETH the curve raises before it graduates
        uint256 sellable; // tokens the curve still sells
        uint160 sqrtPriceX96; // pool price once on Uniswap v4
        uint128 liquidity;
        uint256 feesSplit; // ETH already credited to the X accounts
        uint256 feesPending; // creator fees earned but not split yet (before PonsEarn's share)
        uint64[] xIds;
        string[] handles;
        uint16[] bps;
    }

    IPonsFactory public immutable ponsFactory;
    IPonsEscrow public immutable ponsEscrow;
    IPonsHook public immutable ponsHook;
    IPoolManager public immutable poolManager;
    FeeVault public immutable feeVault;
    FeeSplitter public immutable splitterImplementation;
    PonsEarnRouter public immutable router;

    /// @notice PonsEarn's cut of the standard creator fee, in bps of it (2000 = 20%).
    uint16 public platformShareBps = 2_000;
    /// @notice The Pons launch config coins use (0: ETH-paired, graduating at 4.2 ETH).
    uint256 public launchConfigId;
    /// @notice Bumped whenever a term above changes; a launch pins the version it was shown.
    uint256 public termsVersion = 1;
    bool public launchesPaused;
    /// @notice PonsEarn's share collected so far and not withdrawn yet.
    uint256 public platformFees;
    uint256 public totalPlatformFees;

    Launch[] private _launches;
    mapping(address token => uint256) private _indexOf; // index + 1
    mapping(address token => string[]) private _handlesOf;
    mapping(address splitter => bool) public isSplitter;

    event Launched(
        address indexed token,
        address indexed creator,
        address curve,
        address splitter,
        uint16 creatorTaxBps,
        uint16 platformBps,
        uint256 firstBuy,
        uint256 tokensOut
    );
    event PlatformFee(address indexed token, uint256 amount);
    event PlatformFeesWithdrawn(address indexed to, uint256 amount);
    event PlatformShareSet(uint16 bps);
    event LaunchConfigSet(uint256 id);
    event LaunchesPausedSet(bool paused);

    error LaunchesPaused();
    error TermsChanged();
    error WrongValue(uint256 sent, uint256 expected);
    error ShareTooHigh();
    error NotSplitter();
    error UnexpectedEth();
    error TransferFailed();
    error PonsMismatch();
    error ZeroAddress();

    constructor(address owner_, FeeVault feeVault_, IPonsFactory ponsFactory_) Ownable(owner_) {
        if (address(feeVault_) == address(0) || address(ponsFactory_) == address(0)) revert ZeroAddress();
        feeVault = feeVault_;
        ponsFactory = ponsFactory_;
        ponsEscrow = IPonsEscrow(ponsFactory_.feeEscrow());
        ponsHook = IPonsHook(ponsFactory_.memeHook());
        poolManager = IPoolManager(ponsFactory_.poolManager());
        splitterImplementation = new FeeSplitter(address(this), feeVault_, ponsEscrow, ponsHook);
        router = new PonsEarnRouter(poolManager, ponsFactory_);
    }

    // ----------------------------------------------------------------- launch

    /// @notice Launches a coin on Pons with the X-account split `s`, optionally buying `firstBuy` of it
    ///         for the caller in the same transaction (before anyone else can trade).
    /// @dev msg.value must be exactly Pons's launch fee plus `firstBuy`, so a changed Pons fee reverts
    ///      rather than silently shrinking the buy. The caller is exempt from Pons's opening snipe tax.
    function launch(
        LaunchParams calldata p,
        SplitParams calldata s,
        uint256 firstBuy,
        uint256 minTokensOut,
        uint256 expectedTermsVersion
    ) external payable nonReentrant returns (address token, address curve, address splitter, uint256 tokensOut) {
        if (launchesPaused) revert LaunchesPaused();
        if (expectedTermsVersion != termsVersion) revert TermsChanged();
        uint256 fee = ponsFactory.launchFee();
        if (msg.value != fee + firstBuy) revert WrongValue(msg.value, fee + firstBuy);

        splitter = Clones.clone(address(splitterImplementation));
        address[] memory exempt = new address[](1);
        exempt[0] = msg.sender;
        (token, curve) = ponsFactory.launchToken{value: fee}(
            PonsTokenParams({
                name: p.name,
                symbol: p.symbol,
                logo: p.logo,
                description: p.description,
                socials: p.socials,
                creatorFeeRecipient: splitter,
                creatorTaxBps: p.creatorTaxBps,
                buybackEnabled: false,
                expectedEconomics: p.expectedEconomics,
                salt: keccak256(abi.encode(msg.sender, p.salt))
            }),
            launchConfigId,
            address(0),
            exempt
        );

        PonsLaunchedToken memory rec = ponsFactory.getLaunchedToken(token);
        if (rec.curve != curve || rec.creatorFeeRecipient != splitter || rec.pairToken != address(0)) revert PonsMismatch();
        uint16 pBps = platformBpsFor(IPonsCurve(curve).feeBps(), ponsFactory.getLaunchFeePolicy(token).protocolFeeShareBps, p.creatorTaxBps);
        bytes32 poolId = keccak256(abi.encode(PoolKey(address(0), token, rec.poolFee, rec.tickSpacing, address(ponsHook))));

        FeeSplitter(payable(splitter)).initialize(token, curve, poolId, pBps);
        feeVault.setSplit(token, msg.sender, s.xIds, s.handles, s.bps, s.deadline, s.attestation);
        _launches.push(Launch(token, curve, splitter, msg.sender, uint64(block.timestamp), p.creatorTaxBps, pBps, poolId));
        _indexOf[token] = _launches.length;
        _handlesOf[token] = s.handles;
        isSplitter[splitter] = true;

        if (firstBuy != 0) tokensOut = _firstBuy(curve, firstBuy, minTokensOut);
        emit Launched(token, msg.sender, curve, splitter, p.creatorTaxBps, pBps, firstBuy, tokensOut);
    }

    /// @notice The fraction of every payout (in bps) that PonsEarn's share of the standard creator fee
    ///         amounts to, for a coin with these Pons terms.
    function platformBpsFor(uint256 feeBps, uint256 protocolFeeShareBps, uint16 creatorTaxBps)
        public
        view
        returns (uint16)
    {
        // Both legs in bps² of trade volume: the creator's part of the base fee, and the creator tax.
        uint256 creatorBase = feeBps * (BPS - protocolFeeShareBps);
        uint256 total = creatorBase + uint256(creatorTaxBps) * BPS;
        if (total == 0) return 0;
        return uint16((uint256(platformShareBps) * creatorBase) / total);
    }

    /// @dev Buys for the caller on the new curve. A buy that would run past the curve's allocation is
    ///      filled to the edge and the rest refunded to this contract, which passes it on.
    // The curve is the one Pons just created for this launch, and a refund only goes back to the caller.
    // slither-disable-next-line arbitrary-send-eth
    function _firstBuy(address curve, uint256 amount, uint256 minTokensOut) private returns (uint256 tokensOut) {
        uint256 before = address(this).balance - amount;
        bytes32 slot = REFUNDER_SLOT;
        assembly {
            tstore(slot, curve)
        }
        tokensOut = IPonsCurve(curve).buy{value: amount}(amount, minTokensOut, msg.sender);
        assembly {
            tstore(slot, 0)
        }
        uint256 refund = address(this).balance - before;
        if (refund != 0) {
            (bool ok,) = msg.sender.call{value: refund}("");
            if (!ok) revert TransferFailed();
        }
    }

    /// @dev Only a refund from the curve of the buy in progress is accepted.
    receive() external payable {
        bytes32 slot = REFUNDER_SLOT;
        address refunder;
        assembly {
            refunder := tload(slot)
        }
        if (refunder == address(0) || msg.sender != refunder) revert UnexpectedEth();
    }

    // ------------------------------------------------------------------- fees

    /// @notice Where each coin's FeeSplitter sends PonsEarn's share.
    function platformFeeIn(address token) external payable {
        if (!isSplitter[msg.sender]) revert NotSplitter();
        platformFees += msg.value;
        totalPlatformFees += msg.value;
        emit PlatformFee(token, msg.value);
    }

    /// @notice Collects several coins' fees in one transaction (see FeeSplitter.collect). A coin
    ///         whose collection fails is skipped rather than failing the rest.
    function collectMany(address[] calldata tokens) external returns (uint256 total) {
        for (uint256 i; i < tokens.length; ++i) {
            uint256 index = _indexOf[tokens[i]];
            // slither-disable-next-line incorrect-equality
            if (index == 0) continue;
            try FeeSplitter(payable(_launches[index - 1].splitter)).collect() returns (uint256 amount) {
                total += amount;
            } catch {}
        }
    }

    // ------------------------------------------------------------------ admin

    function withdrawPlatformFees(address to) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = platformFees;
        platformFees = 0;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit PlatformFeesWithdrawn(to, amount);
    }

    /// @notice Applies to coins launched from now on; every existing coin keeps its snapshot.
    function setPlatformShareBps(uint16 bps) external onlyOwner {
        if (bps > MAX_PLATFORM_SHARE_BPS) revert ShareTooHigh();
        platformShareBps = bps;
        termsVersion++;
        emit PlatformShareSet(bps);
    }

    /// @notice Which Pons launch config (an ETH-paired one) new coins use.
    function setLaunchConfigId(uint256 id) external onlyOwner {
        launchConfigId = id;
        termsVersion++;
        emit LaunchConfigSet(id);
    }

    function setLaunchesPaused(bool paused) external onlyOwner {
        launchesPaused = paused;
        emit LaunchesPausedSet(paused);
    }

    // ------------------------------------------------------------------ views

    function launchCount() external view returns (uint256) {
        return _launches.length;
    }

    /// @notice The registry record of a PonsEarn coin (all zero for any other token).
    function launchOf(address token) public view returns (Launch memory l) {
        uint256 index = _indexOf[token];
        if (index != 0) l = _launches[index - 1];
    }

    /// @notice Everything that prices a new launch, read in one call.
    function launchTerms()
        external
        view
        returns (
            uint256 version,
            uint16 platformShare,
            uint256 configId,
            uint256 ponsLaunchFee,
            bytes32 economics,
            uint256 maxCreatorTaxBps,
            bool canLaunch,
            bool paused
        )
    {
        version = termsVersion;
        platformShare = platformShareBps;
        configId = launchConfigId;
        ponsLaunchFee = ponsFactory.launchFee();
        economics = ponsFactory.previewLaunchEconomics(configId, address(0));
        maxCreatorTaxBps = ponsFactory.maxCreatorTaxBps();
        canLaunch = ponsFactory.canLaunch(address(this));
        paused = launchesPaused;
    }

    /// @notice Newest-first page of coins with their live Pons state.
    function getLaunches(uint256 offset, uint256 limit) external view returns (LaunchView[] memory page) {
        uint256 total = _launches.length;
        if (offset >= total) return new LaunchView[](0);
        uint256 n = total - offset < limit ? total - offset : limit;
        page = new LaunchView[](n);
        for (uint256 i; i < n; ++i) {
            page[i] = _view(_launches[total - 1 - offset - i]);
        }
    }

    function getLaunch(address token) external view returns (LaunchView memory v) {
        uint256 index = _indexOf[token];
        if (index != 0) v = _view(_launches[index - 1]);
    }

    function _view(Launch memory l) private view returns (LaunchView memory v) {
        v.launch = l;
        v.name = IERC20Metadata(l.token).name();
        v.symbol = IERC20Metadata(l.token).symbol();
        v.logo = IPonsToken(l.token).logo();
        PonsLaunchedToken memory rec = ponsFactory.getLaunchedToken(l.token);
        v.phase = rec.phase;
        v.feeRecipient = rec.creatorFeeRecipient;
        v.threshold = rec.graduationThreshold;
        // slither-disable-next-line incorrect-equality
        if (rec.phase == 0) {
            IPonsCurve curve = IPonsCurve(l.curve);
            (v.quoteReserve, v.tokenReserve) = curve.getReserves();
            v.raised = curve.realQuoteReserve();
            v.sellable = curve.sellableTokens();
            // slither-disable-next-line incorrect-equality
        } else if (rec.phase == 2) {
            (v.sqrtPriceX96, v.liquidity) = router.poolState(l.poolId);
        }
        v.feesSplit = feeVault.tokenFees(l.token);
        v.feesPending = FeeSplitter(payable(l.splitter)).pendingFees();
        FeeVault.Recipient[] memory split = feeVault.getSplit(l.token);
        v.xIds = new uint64[](split.length);
        v.bps = new uint16[](split.length);
        for (uint256 i; i < split.length; ++i) {
            v.xIds[i] = split[i].xId;
            v.bps[i] = split[i].bps;
        }
        v.handles = _handlesOf[l.token];
    }
}

contracts/PonsEarnRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import {IPonsFactory, PonsLaunchedToken} from "./interfaces/IPons.sol";
import {IPoolManager, IUnlockCallback, PoolKey, SwapParams} from "./interfaces/IUniswapV4.sol";

/// @title PonsEarnRouter
/// @notice Trades a graduated, ETH-paired Pons coin in its Uniswap v4 pool (the one Pons created with
///         its fee hook), with a plain ERC-20 approval for sells. Quotes run the same swap and revert
///         it, so they include Pons's hook fee and creator tax exactly.
/// @dev Stateless and permissionless: it only ever moves the caller's own ETH or tokens, and only to
///      the recipient the caller names. Deployed by PonsEarnLauncher.
contract PonsEarnRouter is IUnlockCallback, ReentrancyGuardTransient {
    using SafeERC20 for IERC20;

    /// @dev TickMath.MIN_SQRT_PRICE + 1 and TickMath.MAX_SQRT_PRICE - 1: no price limit.
    uint160 internal constant MIN_PRICE_LIMIT = 4295128740;
    uint160 internal constant MAX_PRICE_LIMIT = 1461446703485210103287273052203988822378723970341;
    /// @dev StateLibrary.POOLS_SLOT in v4-core: the PoolManager's `_pools` mapping.
    uint256 internal constant POOLS_SLOT = 6;
    uint256 internal constant LIQUIDITY_OFFSET = 3;

    IPoolManager public immutable poolManager;
    IPonsFactory public immutable ponsFactory;
    address public immutable ponsHook;

    struct Swap {
        PoolKey key;
        bool zeroForOne; // true: ETH in, coin out
        uint256 amountIn;
        uint256 minOut;
        address payer;
        address recipient;
        bool quote;
    }

    event PoolTrade(address indexed token, address indexed trader, address indexed recipient, bool isBuy, uint256 ethAmount, uint256 tokenAmount);

    error NotPoolManager();
    error NotOnPool();
    error Expired();
    error ZeroAmount();
    error SlippageExceeded(uint256 amountOut, uint256 minOut);
    error QuoteResult(uint256 amountOut, uint256 amountIn);
    error TransferFailed();

    constructor(IPoolManager poolManager_, IPonsFactory ponsFactory_) {
        poolManager = poolManager_;
        ponsFactory = ponsFactory_;
        ponsHook = ponsFactory_.memeHook();
    }

    // ----------------------------------------------------------------- trades

    /// @notice Buys `token` with all the ETH sent.
    function buy(address token, uint256 minTokensOut, address recipient, uint256 deadline)
        external
        payable
        nonReentrant
        returns (uint256 tokensOut)
    {
        if (block.timestamp > deadline) revert Expired();
        if (msg.value == 0) revert ZeroAmount();
        uint256 paid;
        (tokensOut, paid) = _swap(Swap(poolKeyOf(token), true, msg.value, minTokensOut, msg.sender, recipient, false));
        // A swap stops early only at the price limit; whatever it didn't use goes back.
        if (paid < msg.value) {
            (bool ok,) = msg.sender.call{value: msg.value - paid}("");
            if (!ok) revert TransferFailed();
        }
        emit PoolTrade(token, msg.sender, recipient, true, paid, tokensOut);
    }

    /// @notice Sells `tokensIn` of `token` for ETH. The router must be approved for the amount.
    function sell(address token, uint256 tokensIn, uint256 minEthOut, address recipient, uint256 deadline)
        external
        nonReentrant
        returns (uint256 ethOut)
    {
        if (block.timestamp > deadline) revert Expired();
        if (tokensIn == 0) revert ZeroAmount();
        uint256 paid;
        (ethOut, paid) = _swap(Swap(poolKeyOf(token), false, tokensIn, minEthOut, msg.sender, recipient, false));
        emit PoolTrade(token, msg.sender, recipient, false, ethOut, paid);
    }

    /// @notice What a trade would return right now, fees included. Meant for eth_call: the swap runs
    ///         and is reverted, so nothing changes (and no ETH or approval is needed).
    function quote(address token, bool isBuy, uint256 amountIn) external returns (uint256 amountOut) {
        if (amountIn == 0) return 0;
        bytes memory data = abi.encode(Swap(poolKeyOf(token), isBuy, amountIn, 0, address(0), address(0), true));
        // slither-disable-next-line unused-return
        try poolManager.unlock(data) {
            // unreachable: a quote always reverts with its result
        } catch (bytes memory reason) {
            if (reason.length != 68 || bytes4(reason) != QuoteResult.selector) {
                assembly {
                    revert(add(reason, 32), mload(reason))
                }
            }
            assembly {
                amountOut := mload(add(reason, 36))
            }
        }
    }

    function _swap(Swap memory s) private returns (uint256 amountOut, uint256 paid) {
        (amountOut, paid) = abi.decode(poolManager.unlock(abi.encode(s)), (uint256, uint256));
    }

    /// @dev Runs inside PoolManager.unlock: swap, then pay the input and take the output.
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        Swap memory s = abi.decode(data, (Swap));

        int256 delta = poolManager.swap(
            s.key,
            SwapParams(s.zeroForOne, -int256(s.amountIn), s.zeroForOne ? MIN_PRICE_LIMIT : MAX_PRICE_LIMIT),
            ""
        );
        int128 amount0 = int128(delta >> 128);
        int128 amount1 = int128(delta);
        // Exact input: the input side is owed to the pool (negative), the output side to us.
        (int128 deltaIn, int128 deltaOut) = s.zeroForOne ? (amount0, amount1) : (amount1, amount0);
        uint256 paid = uint256(uint128(-deltaIn));
        uint256 amountOut = uint256(uint128(deltaOut));
        if (s.quote) revert QuoteResult(amountOut, paid);
        if (amountOut < s.minOut) revert SlippageExceeded(amountOut, s.minOut);

        if (s.zeroForOne) {
            // slither-disable-next-line unused-return
            poolManager.settle{value: paid}();
            poolManager.take(s.key.currency1, s.recipient, amountOut);
        } else {
            poolManager.sync(s.key.currency1);
            // `payer` is always the caller of sell(); this callback only runs inside this router's own unlock.
            // slither-disable-next-line arbitrary-send-erc20
            IERC20(s.key.currency1).safeTransferFrom(s.payer, address(poolManager), paid);
            // slither-disable-next-line unused-return
            poolManager.settle();
            poolManager.take(address(0), s.recipient, amountOut);
        }
        return abi.encode(amountOut, paid);
    }

    // ------------------------------------------------------------------ views

    /// @notice The Pons pool of an ETH-paired coin that has graduated; reverts for anything else.
    function poolKeyOf(address token) public view returns (PoolKey memory) {
        PonsLaunchedToken memory rec = ponsFactory.getLaunchedToken(token);
        if (!rec.exists || rec.phase != 2 || rec.pairToken != address(0)) revert NotOnPool();
        return PoolKey(address(0), token, rec.poolFee, rec.tickSpacing, ponsHook);
    }

    /// @notice A pool's current price and in-range liquidity, read from the PoolManager's storage.
    function poolState(bytes32 poolId) public view returns (uint160 sqrtPriceX96, uint128 liquidity) {
        bytes32 stateSlot = keccak256(abi.encode(poolId, POOLS_SLOT));
        sqrtPriceX96 = uint160(uint256(poolManager.extsload(stateSlot)));
        liquidity = uint128(uint256(poolManager.extsload(bytes32(uint256(stateSlot) + LIQUIDITY_OFFSET))));
    }
}

